package uz.hambilite.app;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.Bundle;
import android.text.InputFilter;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.widget.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.Locale;

public class MainActivity extends Activity {
    private static final int YELLOW=Color.rgb(255,204,0), BLACK=Color.rgb(17,18,21), PANEL=Color.rgb(32,34,40), BG=Color.rgb(244,245,247), MUTED=Color.rgb(112,116,125), WHITE=Color.WHITE;
    private LinearLayout root, content, nav;
    private String currentPage="Bosh sahifa";
    @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(BLACK); getWindow().setNavigationBarColor(BLACK); buildShell(); navigate("Bosh sahifa"); showPinGate();}
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private void buildShell(){
        root=column();root.setBackgroundColor(BG);
        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(20),dp(16),dp(20),dp(16));header.setBackgroundColor(BLACK);
        LinearLayout mark=new LinearLayout(this);mark.setGravity(Gravity.CENTER);mark.setBackground(shape(YELLOW,14));TextView h=text("H",25,BLACK,true);h.setGravity(Gravity.CENTER);mark.addView(h,new LinearLayout.LayoutParams(dp(48),dp(48)));header.addView(mark);
        LinearLayout brand=column();brand.setPadding(dp(12),0,0,0);brand.addView(text("Hambi Lite",23,YELLOW,true));brand.addView(text("ALOQA • XIZMATLAR • NAZORAT",10,Color.LTGRAY,true));header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));
        TextView bell=text("●",17,YELLOW,true);bell.setGravity(Gravity.CENTER);header.addView(bell,new LinearLayout.LayoutParams(dp(34),dp(42)));root.addView(header);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);content=column();content.setPadding(dp(16),dp(18),dp(16),dp(20));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        nav=new LinearLayout(this);nav.setBackgroundColor(BLACK);nav.setPadding(dp(5),dp(7),dp(5),dp(7));String[] labels={"Bosh sahifa","Tariflar","Paketlar","Profil"};String[] icons={"⌂","▤","◉","●"};
        for(int i=0;i<labels.length;i++){final String label=labels[i];LinearLayout item=column();item.setGravity(Gravity.CENTER);TextView ico=text(icons[i],21,YELLOW,true);ico.setGravity(Gravity.CENTER);TextView name=text(label,10,Color.WHITE,false);name.setGravity(Gravity.CENTER);item.addView(ico);item.addView(name);item.setPadding(0,dp(5),0,dp(4));item.setOnClickListener(v->navigate(label));nav.addView(item,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);setContentView(root);
    }
    private void navigate(String page){currentPage=page;if(content==null)return; if(page.equals("Bosh sahifa"))showHome();else if(page.equals("Tariflar"))showTariffs();else if(page.equals("Paketlar"))showPackages();else showProfile();}
    private void reset(String title,String subtitle){content.removeAllViews();TextView t=text(title,26,BLACK,true);content.addView(t);TextView s=text(subtitle,13,MUTED,false);s.setPadding(0,dp(5),0,dp(16));content.addView(s);}
    private void section(String s){TextView t=text(s,18,BLACK,true);t.setPadding(0,dp(19),0,dp(10));content.addView(t);}
    private LinearLayout card(){LinearLayout c=column();c.setPadding(dp(16),dp(16),dp(16),dp(16));c.setBackground(shape(WHITE,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);content.addView(c,p);return c;}
    private void showHome(){reset("Salom! 👋","Mobil xizmatlaringiz — bir joyda.");
        LinearLayout balance=column();balance.setPadding(dp(19),dp(19),dp(19),dp(18));balance.setBackground(shape(YELLOW,22));
        LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(text("ASOSIY BALANS",12,BLACK,true),new LinearLayout.LayoutParams(0,-2,1));TextView badge=text("DEMO",10,BLACK,true);badge.setPadding(dp(9),dp(5),dp(9),dp(5));badge.setBackground(shape(Color.rgb(255,225,105),20));top.addView(badge);balance.addView(top);
        TextView amount=text("25 000 so‘m",31,BLACK,true);amount.setPadding(0,dp(8),0,dp(3));balance.addView(amount);balance.addView(text("Namuna qiymati • haqiqiy balans emas",11,Color.rgb(65,61,43),false));
        LinearLayout actions=new LinearLayout(this);actions.setPadding(0,dp(17),0,0);Button check=button("Balansni tekshirish",BLACK,YELLOW);check.setOnClickListener(v->dialUssd("*102#"));actions.addView(check,new LinearLayout.LayoutParams(0,dp(48),1));Button support=button("Yordam",Color.WHITE,BLACK);support.setOnClickListener(v->openUrl("https://beeline.uz/uz/support/"));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,dp(48),1);sp.leftMargin=dp(8);actions.addView(support,sp);balance.addView(actions);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.bottomMargin=dp(16);content.addView(balance,bp);
        section("Paketlaringiz");
        resourceCard("◉","Internet","8 GB","Namuna qoldiq",40,()->dialUssd("*103#"));resourceCard("◔","Daqiqalar","350 daqiqa","Namuna qoldiq",70,()->dialUssd("*106#"));resourceCard("✉","SMS","120 SMS","Namuna qoldiq",60,()->dialUssd("*105#"));
        section("Tezkor xizmatlar");
        quickCard("▤","Tariflar","Tariflarni ko‘rish",()->navigate("Tariflar"));quickCard("◉","Internet paketlar","Paketlar va ulash shartlari",()->navigate("Paketlar"));quickCard("↗","To‘lovlar tarixi","Demo bo‘limi",()->new AlertDialog.Builder(this).setTitle("To‘lovlar tarixi").setMessage("Hozircha tranzaksiyalar tarixi ulanmagan. Bu versiya demo prototip.").setPositiveButton("Tushunarli",null).show());quickCard("?","Yordam markazi","Rasmiy yordam sahifasi",()->openUrl("https://beeline.uz/uz/support/"));note("Muhim: balans va qoldiq raqamlari namuna uchun. Haqiqiy ma’lumotlar uchun operatorning ruxsatli integratsiyasi kerak.");
    }
    private void resourceCard(String icon,String title,String amount,String detail,int percent,Runnable action){LinearLayout c=card();LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView i=text(icon,23,YELLOW,true);i.setGravity(Gravity.CENTER);i.setBackground(shape(BLACK,13));row.addView(i,new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout middle=column();middle.setPadding(dp(12),0,0,0);middle.addView(text(title,15,BLACK,true));middle.addView(text(detail,11,MUTED,false));row.addView(middle,new LinearLayout.LayoutParams(0,-2,1));LinearLayout right=column();right.setGravity(Gravity.RIGHT);right.addView(text(amount,15,BLACK,true));right.addView(text(percent+"%",11,MUTED,false));row.addView(right);c.addView(row);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(percent);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(YELLOW));bar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(232,233,236)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(6));p.topMargin=dp(13);p.bottomMargin=dp(10);c.addView(bar,p);TextView b=text("Qoldiqni tekshirish  →",12,BLACK,true);b.setGravity(Gravity.RIGHT);c.addView(b);c.setOnClickListener(v->action.run());}
    private void quickCard(String icon,String title,String detail,Runnable action){LinearLayout c=card();c.setOrientation(LinearLayout.HORIZONTAL);c.setGravity(Gravity.CENTER_VERTICAL);TextView i=text(icon,21,YELLOW,true);i.setGravity(Gravity.CENTER);i.setBackground(shape(BLACK,13));c.addView(i,new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout words=column();words.setPadding(dp(12),0,0,0);words.addView(text(title,15,BLACK,true));words.addView(text(detail,12,MUTED,false));c.addView(words,new LinearLayout.LayoutParams(0,-2,1));c.addView(text("›",27,MUTED,false));c.setOnClickListener(v->action.run());}
    private void showTariffs(){reset("Tariflar","Mos tarifni tanlashdan oldin rasmiy shartlarni tekshiring.");LinearLayout featured=column();featured.setPadding(dp(18),dp(18),dp(18),dp(18));featured.setBackground(shape(BLACK,20));featured.addView(text("TARIFLAR KATALOGI",11,YELLOW,true));TextView t=text("O‘zingizga mos tarifni toping",22,WHITE,true);t.setPadding(0,dp(9),0,dp(8));featured.addView(t);featured.addView(text("Narxlar va shartlar operator tomonidan o‘zgarishi mumkin.",13,Color.LTGRAY,false));Button b=button("Rasmiy tariflarni ochish",YELLOW,BLACK);b.setOnClickListener(v->openUrl("https://beeline.uz/uz/products/tariffs"));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.topMargin=dp(16);featured.addView(b,p);content.addView(featured);section("Foydali havolalar");quickCard("▤","Barcha tariflar","Rasmiy tariflar ro‘yxati",()->openUrl("https://beeline.uz/uz/products/tariffs"));quickCard("◎","Shaxsiy kabinet","Rasmiy sayt orqali kirish",()->openUrl("https://beeline.uz/uz"));note("Bu prototip tarifni avtomatik almashtirmaydi. Xarid yoki ulashdan oldin rasmiy shartlarni o‘qing.");}
    private void showPackages(){reset("Paketlar","Internet va aloqa xizmatlarini boshqarish.");quickCard("◉","Internet paketlari","Paketlar haqidagi rasmiy ma’lumot",()->openUrl("https://beeline.uz/uz"));quickCard("◔","Internet qoldig‘i","USSD orqali tekshirish • *103#",()->dialUssd("*103#"));quickCard("◌","Daqiqalar qoldig‘i","USSD orqali tekshirish • *106#",()->dialUssd("*106#"));quickCard("✉","SMS qoldig‘i","USSD orqali tekshirish • *105#",()->dialUssd("*105#"));note("Paketni ilova ichida sotib olish hozircha yoqilmagan. Rasmiy ulash sahifasidan foydalaning.");}
    private void showProfile(){reset("Profil","Ilova sozlamalari va yordam.");LinearLayout p=card();p.setBackground(shape(BLACK,20));p.addView(text("Hambi Lite",22,YELLOW,true));p.addView(text("Sodda. Qulay. Nazorat ostida.",13,Color.LTGRAY,false));TextView ver=text("VERSIYA 1.1 • JAVA ANDROID",10,Color.LTGRAY,true);ver.setPadding(0,dp(12),0,0);p.addView(ver);section("Sozlamalar");quickCard("⌑","PIN-kodni o‘zgartirish","Ilovaga kirish kodini yangilash",()->changePin());quickCard("?","Yordam markazi","Savol va murojaatlar",()->openUrl("https://beeline.uz/uz/support/"));quickCard("↗","Rasmiy Beeline sayti","Tariflar va xizmatlar",()->openUrl("https://beeline.uz/uz"));quickCard("i","Ilova haqida","Hambi Lite mustaqil prototip",()->new AlertDialog.Builder(this).setTitle("Hambi Lite").setMessage("Bu mustaqil Android prototipi, Beeline yoki Hambi rasmiy ilovasi emas. Balans va paket qoldiqlari demo ko‘rinishida.").setPositiveButton("Yopish",null).show());}
    private void note(String s){TextView n=text(s,11,MUTED,false);n.setPadding(dp(4),dp(10),dp(4),dp(8));content.addView(n);}
    private Button button(String label,int bg,int fg){Button b=new Button(this);b.setText(label);b.setTextColor(fg);b.setTextSize(12);b.setAllCaps(false);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(bg));return b;}
    private SharedPreferences prefs(){return getSharedPreferences("hambi_security",MODE_PRIVATE);}private String hash(String s){try{byte[] d=MessageDigest.getInstance("SHA-256").digest((getPackageName()+":hambi-lite:"+s).getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:d)b.append(String.format(Locale.US,"%02x",x));return b.toString();}catch(Exception e){return s;}}
    private EditText pinInput(String hint){EditText e=new EditText(this);e.setHint(hint);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(4)});return e;}
    private void showPinGate(){String saved=prefs().getString("pin_hash",null);if(saved==null)pinDialog(true);else pinDialog(false);}
    private void pinDialog(boolean setup){LinearLayout box=column();box.setPadding(dp(18),0,dp(18),0);EditText a=pinInput(setup?"Yangi 4 xonali PIN":"4 xonali PIN");box.addView(a);EditText b=null;if(setup){b=pinInput("PINni qayta kiriting");box.addView(b);}final EditText confirm=b;AlertDialog d=new AlertDialog.Builder(this).setTitle(setup?"Himoya kodini yarating":"Hambi Lite — kirish").setMessage(setup?"PIN keyingi ochishlarda so‘raladi.":"Davom etish uchun PIN kiriting.").setView(box).setCancelable(false).setPositiveButton(setup?"Saqlash":"Kirish",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String pin=a.getText().toString();if(!pin.matches("[0-9]{4}")){a.setError("4 ta raqam kiriting");return;}if(setup){if(!pin.equals(confirm.getText().toString())){confirm.setError("Kodlar mos emas");return;}prefs().edit().putString("pin_hash",hash(pin)).apply();}else if(!hash(pin).equals(prefs().getString("pin_hash",""))){a.setError("PIN noto‘g‘ri");a.setText("");return;}d.dismiss();}));d.show();d.getButton(-1).setOnClickListener(w->{String pin=a.getText().toString();if(!pin.matches("[0-9]{4}")){a.setError("4 ta raqam kiriting");return;}if(setup){if(!pin.equals(confirm.getText().toString())){confirm.setError("Kodlar mos emas");return;}prefs().edit().putString("pin_hash",hash(pin)).apply();}else if(!hash(pin).equals(prefs().getString("pin_hash",""))){a.setError("PIN noto‘g‘ri");a.setText("");return;}d.dismiss();});}
    private void changePin(){EditText old=pinInput("Hozirgi PIN"),n=pinInput("Yangi PIN"),c=pinInput("Yangi PINni qayta kiriting");LinearLayout box=column();box.setPadding(dp(18),0,dp(18),0);box.addView(old);box.addView(n);box.addView(c);AlertDialog d=new AlertDialog.Builder(this).setTitle("PINni o‘zgartirish").setView(box).setNegativeButton("Bekor",null).setPositiveButton("Saqlash",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{if(!hash(old.getText().toString()).equals(prefs().getString("pin_hash",""))){old.setError("Eski PIN noto‘g‘ri");return;}if(!n.getText().toString().matches("[0-9]{4}")){n.setError("4 ta raqam kiriting");return;}if(!n.getText().toString().equals(c.getText().toString())){c.setError("Kodlar mos emas");return;}prefs().edit().putString("pin_hash",hash(n.getText().toString())).apply();d.dismiss();Toast.makeText(this,"PIN o‘zgartirildi",Toast.LENGTH_SHORT).show();}));d.show();d.getButton(-1).setOnClickListener(w->{if(!hash(old.getText().toString()).equals(prefs().getString("pin_hash",""))){old.setError("Eski PIN noto‘g‘ri");return;}if(!n.getText().toString().matches("[0-9]{4}")){n.setError("4 ta raqam kiriting");return;}if(!n.getText().toString().equals(c.getText().toString())){c.setError("Kodlar mos emas");return;}prefs().edit().putString("pin_hash",hash(n.getText().toString())).apply();d.dismiss();Toast.makeText(this,"PIN o‘zgartirildi",Toast.LENGTH_SHORT).show();});}
    private void dialUssd(String code){try{startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+Uri.encode(code))));}catch(Exception e){Toast.makeText(this,"Terish oynasini ochib bo‘lmadi",Toast.LENGTH_LONG).show();}}
    private void openUrl(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"Sahifani ochib bo‘lmadi",Toast.LENGTH_LONG).show();}}
}
